def extract_amount_from_line(line):
    """
    Extract monetary amount from a line.
    Handles formats like: 123.45, 1,234.56, RM 123.45, $ 123.45
    """
    # Pattern to match monetary amounts
    # Matches: optional currency symbol, digits with optional commas, decimal point, two digits
    patterns = [
        r'(?:RM|MYR|\$|USD)?\s*([0-9]{1,3}(?:,[0-9]{3})*\.[0-9]{2})',  # With comma separators
        r'(?:RM|MYR|\$|USD)?\s*([0-9]+\.[0-9]{2})',  # Simple format
        r':\s*([0-9]{1,3}(?:,[0-9]{3})*\.[0-9]{2})',  # After colon
        r':\s*([0-9]+\.[0-9]{2})',  # After colon, simple
    ]

    for pattern in patterns:
        matches = re.findall(pattern, line)
        if matches:
            # Return the last match (usually the total is the last number on the line)
            amount_str = matches[-1].replace(',', '')
            try:
                return float(amount_str)
            except ValueError:
                continue

    return None

